#include "ksMidiFileTimeTask.h"
#include <array>
#include <cstdint>
#include <iostream>
#include <stdexcept>
using T=ks::MidiFileTimeTask;using S=T::Stage;using K=T::Kind;
void check(bool b,const char*m){if(!b)throw std::runtime_error(m);}struct Vlq{uint32_t value;unsigned bytes;};Vlq oracle(std::array<uint8_t,4>a){uint32_t value=0;for(unsigned i=0;i<4;++i){value=value*128u+(i==3?a[i]:a[i]&127u);if(i==3||a[i]<128)return{value,i+1};}throw 0;}
int main(){try{uint64_t cases=0;auto verify=[&](unsigned kind,uint32_t encoded,uint32_t input,uint32_t deadline,uint32_t base){std::array<uint8_t,4>a{uint8_t(encoded>>24),uint8_t(encoded>>16),uint8_t(encoded>>8),uint8_t(encoded)};auto expected=oracle(a);T t{K(kind),base,input,0xfffffff0};unsigned publications=0,divisionReads=0;uint32_t published=0;while(!t.complete()){if(t.awaitingChild()){check(t.stream()==base,"VLQ child source binding");check(t.resumeVlq(expected.value,base+expected.bytes),"VLQ childreply");continue;}auto read=[&](S s)->uint32_t{switch(s){case S::VlqReadFirst:case S::VlqReadSecond:case S::VlqReadThird:case S::VlqReadFourth:{auto offset=uint32_t(t.stream()-base);check(offset<4,"VLQ overread");return a[offset];}case S::DueReadNow:return input;case S::TempoReadDivision:++divisionReads;return encoded&65535;default:return deadline;}};auto write=[&](S,uint32_t v){++publications;published=v;};auto before=t.stage();auto cost=t.nextClocks(6);check(cost&&t.advanceBefore(cost-1,read,write,[](S){return 6u;})==0&&before==t.stage(),"Early file-time deadline");check(t.advanceBefore(cost,read,write,[](S){return 6u;})==cost,"File-time deadline");}if(kind==2){check(t.value()==expected.value&&t.stream()==base+expected.bytes,"Unsigned VLQ value/cursor");check(!publications,"VLQ spuriouspublish");}else if(kind==0||kind==4){check(publications==1&&published==deadline+(expected.value<<12),"Unsigned scaled deadline");check(t.stream()==base+expected.bytes,"Delay source reply");}else if(kind==1){check(t.due()==(input>=deadline)&&!publications,"Due unsigned comparator");}else{uint16_t divisor=uint16_t(input>>4);uint16_t period=divisor?uint16_t(98304000u/divisor):0;check(publications==1&&published==period&&t.period()==period&&divisionReads==1,"Tempo fixedscale/divide/truncate or ignored PPQ read");}++cases;};
for(unsigned first=0;first<256;++first)for(unsigned second=0;second<256;++second)for(unsigned third:{0u,127u,128u,255u})verify(2,(first<<24)|(second<<16)|(third<<8)|255,0,0,first&1?0xfffffffeu:0xffa31001u);
for(unsigned third=0;third<256;++third)for(unsigned fourth=0;fourth<256;++fourth)verify(2,0xffff0000u|(third<<8)|fourth,0,0,0xffffffffu);
for(unsigned divisor=0;divisor<65536;++divisor)for(unsigned top:{0u,0xfff00000u})verify(3,divisor*0x10001u,top+divisor*16u+15,0,0);
for(unsigned kind:{0u,1u,4u})for(unsigned value=0;value<65536;++value)verify(kind,0xffff0000u|value,value*0x10001u,0xffffffffu-value*0x10001u,0xfffffffeu);
std::cout<<"PASS: "<<cases<<" pure MIDI-file VLQ/time/tempo tasks, independent base128/deadline/unsigned-due/fixed-tempo oracles, all divisor and raw fourth-byte values, pointer wrap and early deadlines\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
